-- 029: authenticated marketplace snapshot, safe assistant rate-limit entry point, and initial reviewed source set
create or replace function public.consume_assistant_rate_limit() returns boolean language sql security invoker set search_path='' as $$ select private.consume_assistant_rate_limit(); $$;
revoke all on function public.consume_assistant_rate_limit() from public,anon;
grant execute on function public.consume_assistant_rate_limit() to authenticated;
create or replace function public.get_assistant_marketplace_snapshot() returns jsonb language sql stable security invoker set search_path='' as $$ select jsonb_build_object('as_of',now(),'profile',(select jsonb_build_object('role',p.role,'locality',p.locality,'municipality',p.municipality,'district',p.district) from public.profiles p where p.id=auth.uid()),'subscription',(select jsonb_build_object('plan',s.plan,'status',s.status,'current_period_end',s.current_period_end) from public.farmer_subscriptions s where s.farmer_id=auth.uid() and s.status in ('active','trialing') and (s.current_period_end is null or s.current_period_end>now()) order by s.current_period_end desc nulls last limit 1),'listings',jsonb_build_object('total',(select count(*) from public.produce_listings l where l.farmer_id=auth.uid()),'active',(select count(*) from public.produce_listings l where l.farmer_id=auth.uid() and l.status='active'),'limit',case coalesce((select s.plan from public.farmer_subscriptions s where s.farmer_id=auth.uid() and s.status in ('active','trialing') and (s.current_period_end is null or s.current_period_end>now()) order by s.current_period_end desc nulls last limit 1),'free') when 'premium' then 200 when 'pro' then 50 else 10 end),'seller',jsonb_build_object('allocation_count',(select count(*) from public.order_allocations a where a.farmer_id=auth.uid()),'fulfilled_allocations',(select count(*) from public.order_allocations a where a.farmer_id=auth.uid() and a.status='fulfilled'),'fulfilled_sales_value',(select coalesce(sum(a.quantity_allocated*a.agreed_unit_price),0) from public.order_allocations a where a.farmer_id=auth.uid() and a.status='fulfilled'),'open_allocations',(select count(*) from public.order_allocations a where a.farmer_id=auth.uid() and a.status not in ('fulfilled','rejected','cancelled')),'delivery_orders',(select count(*) from public.order_allocations a join public.orders o on o.id=a.order_id where a.farmer_id=auth.uid() and o.fulfilment_method='delivery'),'scheduled_deliveries',(select count(*) from public.order_allocations a join public.orders o on o.id=a.order_id where a.farmer_id=auth.uid() and o.fulfilment_method='delivery' and o.fulfilment_state in ('scheduled_for_delivery','out_for_delivery'))),'buyer',jsonb_build_object('order_count',(select count(*) from public.orders o where o.buyer_id=auth.uid()),'fulfilled_orders',(select count(*) from public.orders o where o.buyer_id=auth.uid() and o.status='fulfilled'),'fulfilled_spend',(select coalesce(sum(o.quantity_agreed*o.unit_price+coalesce(o.delivery_fee,0)),0) from public.orders o where o.buyer_id=auth.uid() and o.status='fulfilled'),'open_orders',(select count(*) from public.orders o where o.buyer_id=auth.uid() and o.status not in ('fulfilled','rejected','cancelled'))),'bookkeeping',jsonb_build_object('income',(select coalesce(sum(e.amount),0) from public.farm_bookkeeping_entries e where e.owner_id=auth.uid() and e.entry_type='income'),'expenses',(select coalesce(sum(e.amount),0) from public.farm_bookkeeping_entries e where e.owner_id=auth.uid() and e.entry_type='expense'),'unpaid_income',(select coalesce(sum(e.amount),0) from public.farm_bookkeeping_entries e where e.owner_id=auth.uid() and e.entry_type='income' and e.payment_status='unpaid'))); $$;
revoke all on function public.get_assistant_marketplace_snapshot() from public,anon;
grant execute on function public.get_assistant_marketplace_snapshot() to authenticated;
insert into public.agri_knowledge_sources(title,publisher,source_url,source_type,locality_tags,crop_tags,status,reviewed_at) values ('Tomato Production in Limpopo Province','Limpopo Department of Agriculture and Rural Development','https://www.ldard.gov.za/index.php/tomato-production-in-limpopo-province','government',array['Limpopo','Vhembe'],array['tomato'],'approved',now()),('Crop Production Guide','Limpopo Department of Agriculture and Rural Development','https://www.ldard.gov.za/index.php/crop-production-guide','government',array['Limpopo','Vhembe'],array['cabbage','carrot','onion','tomato','spinach','beetroot'],'approved',now()),('Production guideline for African leafy vegetable cultivation in Capricorn and Vhembe districts','Water Research Commission','https://www.wrc.org.za/mdocs-posts/production-guideline-for-african-leafy-vegetable-cultivation-in-the-capricorn-and-vhembe-districts-in-limpopo/','research',array['Limpopo','Vhembe','Capricorn'],array['African leafy vegetables','indigenous vegetables'],'approved',now()),('ARC Information Hub','Agricultural Research Council','https://www.arc.agric.za/Pages/ARC-Information-Hub.aspx','extension',array['South Africa','Limpopo'],array['maize','sorghum','cowpea','dry bean','groundnut','soybean','sunflower'],'approved',now()) on conflict(source_url) do update set title=excluded.title,publisher=excluded.publisher,locality_tags=excluded.locality_tags,crop_tags=excluded.crop_tags,status='approved',reviewed_at=now();
insert into public.agri_knowledge_chunks(source_id,chunk_index,heading,content,locality_tags,crop_tags) select s.id,0,'Tomato soil, temperature and field preparation','The Limpopo Department of Agriculture and Rural Development tomato guide says tomatoes prefer deep, well-aerated soils with organic matter. Organic matter supports soil structure and improves water and nutrient retention, infiltration and aeration. The guide reports best production around average temperatures of 20–24°C; temperatures above 30°C can negatively affect fruit set. Soil preparation should be adapted to soil texture rather than treated as one universal recipe. The guide describes preparation depths of 200–400 mm and contour-aligned ridging to help drainage and root-zone aeration.',array['Limpopo','Vhembe'],array['tomato'] from public.agri_knowledge_sources s where s.source_url='https://www.ldard.gov.za/index.php/tomato-production-in-limpopo-province' on conflict(source_id,chunk_index) do update set heading=excluded.heading,content=excluded.content,locality_tags=excluded.locality_tags,crop_tags=excluded.crop_tags;
insert into public.agri_knowledge_chunks(source_id,chunk_index,heading,content,locality_tags,crop_tags) select s.id,1,'Tomato fertilisation, irrigation and crop health','The Limpopo tomato guide says fertiliser programmes should be based on soil analysis and crop growth stage. It describes higher nitrogen demand during early vegetative growth, and calcium and magnesium needs during flowering, fruit set and fruit filling. It identifies drip or flood irrigation as methods used for tomatoes and notes that water demand changes with weather and growth stage, with the highest use around fruit set. It lists early and late blight, powdery mildew, Fusarium diseases, bacterial spot, Tuta absoluta and root-knot nematodes among tomato health concerns. For Tuta absoluta, the guide stresses resistance management and crop rotation. Confirm chemical choices and rates with a registered local extension officer and current product labels.',array['Limpopo','Vhembe'],array['tomato','irrigation','fertiliser','pest management'] from public.agri_knowledge_sources s where s.source_url='https://www.ldard.gov.za/index.php/tomato-production-in-limpopo-province' on conflict(source_id,chunk_index) do update set heading=excluded.heading,content=excluded.content,locality_tags=excluded.locality_tags,crop_tags=excluded.crop_tags;
insert into public.agri_knowledge_chunks(source_id,chunk_index,heading,content,locality_tags,crop_tags) select s.id,0,'Limpopo crop production guides','The Limpopo Department of Agriculture and Rural Development Crop Production Guide index links province-specific production guides for cabbage, carrot, onion, tomato, spinach and beetroot. Use the individual crop guide for crop-specific recommendations. The index itself is a catalogue and does not provide all production rates or planting calendars.',array['Limpopo','Vhembe'],array['cabbage','carrot','onion','tomato','spinach','beetroot'] from public.agri_knowledge_sources s where s.source_url='https://www.ldard.gov.za/index.php/crop-production-guide' on conflict(source_id,chunk_index) do update set heading=excluded.heading,content=excluded.content,locality_tags=excluded.locality_tags,crop_tags=excluded.crop_tags;
insert into public.agri_knowledge_chunks(source_id,chunk_index,heading,content,locality_tags,crop_tags) select s.id,0,'Vhembe African leafy vegetable production resource','The Water Research Commission lists a production guideline specifically covering African leafy vegetable cultivation in the Capricorn and Vhembe districts of Limpopo. This source is geographically relevant to Vhembe. The catalogue record identifies the publication and download, but detailed crop-specific practices must be checked in the full guideline before giving precise planting, fertiliser or pesticide recommendations.',array['Limpopo','Vhembe','Capricorn'],array['African leafy vegetables','indigenous vegetables'] from public.agri_knowledge_sources s where s.source_url='https://www.wrc.org.za/mdocs-posts/production-guideline-for-african-leafy-vegetable-cultivation-in-the-capricorn-and-vhembe-districts-in-limpopo/' on conflict(source_id,chunk_index) do update set heading=excluded.heading,content=excluded.content,locality_tags=excluded.locality_tags,crop_tags=excluded.crop_tags;
insert into public.agri_knowledge_chunks(source_id,chunk_index,heading,content,locality_tags,crop_tags) select s.id,0,'ARC crop information and production resources','The Agricultural Research Council Information Hub provides crop and production resources covering summer grains and oilseeds including maize, sorghum, cowpeas, dry beans, groundnuts, soybeans and sunflower, alongside crop protection and training information. The hub is an index to ARC resources; consult the linked crop-specific publication for detailed local recommendations.',array['South Africa','Limpopo'],array['maize','sorghum','cowpea','dry bean','groundnut','soybean','sunflower'] from public.agri_knowledge_sources s where s.source_url='https://www.arc.agric.za/Pages/ARC-Information-Hub.aspx' on conflict(source_id,chunk_index) do update set heading=excluded.heading,content=excluded.content,locality_tags=excluded.locality_tags,crop_tags=excluded.crop_tags;